/* deriche.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "deriche.h"


/* Array initialization. */
static
void init_array (int w, int h, DATA_TYPE* alpha,
		 DATA_TYPE POLYBENCH_2D(imgIn,W,H,w,h),
		 DATA_TYPE POLYBENCH_2D(imgOut,W,H,w,h))
{
  int i, j;

  *alpha=0.25; //parameter of the filter

  //input should be between 0 and 1 (grayscale image pixel)
  for (i = 0; i < w; i++)
     for (j = 0; j < h; j++)
	imgIn[i][j] = (DATA_TYPE) ((313*i+991*j)%65536) / 65535.0f;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int w, int h,
		 DATA_TYPE POLYBENCH_2D(imgOut,W,H,w,h))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("imgOut");
  for (i = 0; i < w; i++)
    for (j = 0; j < h; j++) {
      if ((i * h + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, imgOut[i][j]);
    }
  POLYBENCH_DUMP_END("imgOut");
  POLYBENCH_DUMP_FINISH;
}



/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* Original code provided by Gael Deest */

/*
 * Optimized version:
 *  - Precomputes exponentials used multiple times.
 *  - Improves cache locality for vertical passes by processing in
 *    row-major order using per-column state arrays.
 *  - Uses OpenMP pragmas for parallelism on embarrassingly parallel passes.
 *  - Uses row pointers and (implicit) non-aliasing assumptions to help
 *    the compiler vectorize inner loops.
 *
 * Semantics of the original algorithm are preserved:
 *  - The 1D recursive Deriche filter is still applied first horizontally
 *    (forward and reverse), combined, then vertically (forward and reverse),
 *    and combined again.
 *  - For each row/column, the order of recursive operations along that
 *    row/column is unchanged; only the interleaving between columns changes,
 *    which does not affect correctness because columns are independent.
 */
static
void __attribute__((flatten, noinline))
kernel_deriche(int w, int h, DATA_TYPE alpha,
       DATA_TYPE POLYBENCH_2D(imgIn, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y1, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y2, W, H, w, h))
{
    /* Use the PolyBench loop bounds to preserve original behavior. */
    const int w_ = _PB_W;
    const int h_ = _PB_H;

    /* Filter coefficients. */
    DATA_TYPE k;
    DATA_TYPE a1, a2, a3, a4, a5, a6, a7, a8;
    DATA_TYPE b1, b2, c1, c2;

#pragma scop
    /* Precompute frequently used scalar values and exponentials. */
    const DATA_TYPE one  = SCALAR_VAL(1.0);
    const DATA_TYPE two  = SCALAR_VAL(2.0);
    const DATA_TYPE neg_alpha   = -alpha;
    const DATA_TYPE exp_neg_a   = EXP_FUN(neg_alpha);          /* e^{-alpha}   */
    const DATA_TYPE neg_2alpha  = -two * alpha;
    const DATA_TYPE exp_neg_2a  = EXP_FUN(neg_2alpha);         /* e^{-2alpha}  */
    const DATA_TYPE pos_2alpha  =  two * alpha;
    const DATA_TYPE exp_pos_2a  = EXP_FUN(pos_2alpha);         /* e^{ 2alpha}  */

    /* Normalization factor k and IIR coefficients (same formulas as original). */
    k  = (one - exp_neg_a) * (one - exp_neg_a)
       / (one + two * alpha * exp_neg_a - exp_pos_2a);

    a1 = a5 = k;
    a2 = a6 = k * exp_neg_a * (alpha - one);
    a3 = a7 = k * exp_neg_a * (alpha + one);
    a4 = a8 = -k * exp_neg_2a;

    b1 = POW_FUN(two, neg_alpha);   /* 2^{-alpha} */
    b2 = -exp_neg_2a;

    c1 = c2 = one;

    /* ---------------------------------------------------------------------
     * Horizontal passes (good locality already: j is the fast index).
     * Each row is independent and can be processed in parallel.
     * ------------------------------------------------------------------ */

    /* Horizontal forward pass (left-to-right). */
    #pragma omp parallel for schedule(static)
    for (int i = 0; i < w_; i++) {
        DATA_TYPE ym1 = SCALAR_VAL(0.0);
        DATA_TYPE ym2 = SCALAR_VAL(0.0);
        DATA_TYPE xm1 = SCALAR_VAL(0.0);

        DATA_TYPE *restrict imgIn_row = imgIn[i];
        DATA_TYPE *restrict y1_row    = y1[i];

        for (int j = 0; j < h_; j++) {
            const DATA_TYPE x = imgIn_row[j];
            const DATA_TYPE y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;
            y1_row[j] = y;

            xm1 = x;
            ym2 = ym1;
            ym1 = y;
        }
    }

    /* Horizontal reverse pass (right-to-left). */
    #pragma omp parallel for schedule(static)
    for (int i = 0; i < w_; i++) {
        DATA_TYPE yp1 = SCALAR_VAL(0.0);
        DATA_TYPE yp2 = SCALAR_VAL(0.0);
        DATA_TYPE xp1 = SCALAR_VAL(0.0);
        DATA_TYPE xp2 = SCALAR_VAL(0.0);

        DATA_TYPE *restrict imgIn_row = imgIn[i];
        DATA_TYPE *restrict y2_row    = y2[i];

        for (int j = h_ - 1; j >= 0; j--) {
            const DATA_TYPE y = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            y2_row[j] = y;

            xp2 = xp1;
            xp1 = imgIn_row[j];
            yp2 = yp1;
            yp1 = y;
        }
    }

    /* Combine horizontal forward and reverse passes. */
    #pragma omp parallel for schedule(static)
    for (int i = 0; i < w_; i++) {
        DATA_TYPE *restrict y1_row  = y1[i];
        DATA_TYPE *restrict y2_row  = y2[i];
        DATA_TYPE *restrict out_row = imgOut[i];

        for (int j = 0; j < h_; j++) {
            out_row[j] = c1 * (y1_row[j] + y2_row[j]);
        }
    }

    /* ---------------------------------------------------------------------
     * Vertical passes.
     *
     * Original code processes one column at a time:
     *   for each column j:
     *     reset state;
     *     for each row i:  recursive update along i
     *
     * Because arrays are row-major [w][h], that access pattern is
     * highly strided (step = h elements) and cache-unfriendly.
     *
     * Here, we process in row-major order instead:
     *   - We keep per-column state in temporary 1D arrays (tm1_col, etc.).
     *   - We sweep rows i in order, and for each row update all columns j.
     * This preserves the exact recursive dependence along i for each column,
     * but turns memory accesses on imgOut/y1/y2 into contiguous row walks,
     * greatly improving cache locality.
     *
     * Memory overhead is small: 7 * h_ scalars << 0.5 * 4 * w_ * h_.
     * ------------------------------------------------------------------ */

    /* Per-column state for vertical forward pass. */
    DATA_TYPE tm1_col[h_];
    DATA_TYPE ym1_col[h_];
    DATA_TYPE ym2_col[h_];

    /* Initialize vertical forward states (equivalent to resetting tm1, ym1,
       ym2 to 0 at the beginning of each column in the original code). */
    for (int j = 0; j < h_; j++) {
        tm1_col[j] = SCALAR_VAL(0.0);
        ym1_col[j] = SCALAR_VAL(0.0);
        ym2_col[j] = SCALAR_VAL(0.0);
    }

    /* Vertical forward pass (top-to-bottom), processed by rows. */
    for (int i = 0; i < w_; i++) {
        DATA_TYPE *restrict out_row = imgOut[i];
        DATA_TYPE *restrict y1_row  = y1[i];

        for (int j = 0; j < h_; j++) {
            const DATA_TYPE tm1 = tm1_col[j];
            const DATA_TYPE ym1 = ym1_col[j];
            const DATA_TYPE ym2 = ym2_col[j];

            const DATA_TYPE x = out_row[j];
            const DATA_TYPE y = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;

            y1_row[j]   = y;
            tm1_col[j]  = x;
            ym2_col[j]  = ym1;
            ym1_col[j]  = y;
        }
    }

    /* Per-column state for vertical reverse pass. */
    DATA_TYPE tp1_col[h_];
    DATA_TYPE tp2_col[h_];
    DATA_TYPE yp1_col[h_];
    DATA_TYPE yp2_col[h_];

    /* Initialize vertical reverse states (equivalent to resetting tp1, tp2,
       yp1, yp2 to 0 at the beginning of each column in the original code). */
    for (int j = 0; j < h_; j++) {
        tp1_col[j] = SCALAR_VAL(0.0);
        tp2_col[j] = SCALAR_VAL(0.0);
        yp1_col[j] = SCALAR_VAL(0.0);
        yp2_col[j] = SCALAR_VAL(0.0);
    }

    /* Vertical reverse pass (bottom-to-top), processed by rows.
       For each column j, this reproduces the original recursion:
       we start at i = w_ - 1 with zero state and move upward. */
    for (int i = w_ - 1; i >= 0; i--) {
        DATA_TYPE *restrict out_row = imgOut[i];
        DATA_TYPE *restrict y2_row  = y2[i];

        for (int j = 0; j < h_; j++) {
            const DATA_TYPE tp1 = tp1_col[j];
            const DATA_TYPE tp2 = tp2_col[j];
            const DATA_TYPE yp1 = yp1_col[j];
            const DATA_TYPE yp2 = yp2_col[j];

            const DATA_TYPE y = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
            y2_row[j] = y;

            const DATA_TYPE x = out_row[j];
            tp2_col[j] = tp1;
            tp1_col[j] = x;
            yp2_col[j] = yp1;
            yp1_col[j] = y;
        }
    }

    /* Final combination of vertical forward and reverse passes. */
    #pragma omp parallel for schedule(static)
    for (int i = 0; i < w_; i++) {
        DATA_TYPE *restrict y1_row  = y1[i];
        DATA_TYPE *restrict y2_row  = y2[i];
        DATA_TYPE *restrict out_row = imgOut[i];

        for (int j = 0; j < h_; j++) {
            out_row[j] = c2 * (y1_row[j] + y2_row[j]);
        }
    }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int w = W;
  int h = H;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(imgIn, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(imgOut, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y1, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y2, DATA_TYPE, W, H, w, h);


  /* Initialize array(s). */
  init_array (w, h, &alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_deriche (w, h, alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut),
                  POLYBENCH_ARRAY(y1), POLYBENCH_ARRAY(y2));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(w, h, POLYBENCH_ARRAY(imgOut)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(imgIn);
  POLYBENCH_FREE_ARRAY(imgOut);
  POLYBENCH_FREE_ARRAY(y1);
  POLYBENCH_FREE_ARRAY(y2);

  return 0;
}
