     assume non-aliasing between arrays and improve vectorization.
   - Fuse passes that operate on the same row/column to improve
     cache locality.
   - Parallelize independent outer loops with OpenMP (if enabled
     at compile time); pragmas are ignored otherwise.
*/
static
void kernel_deriche[[gnu::flatten, gnu::noinline]](int w, int h, DATA_TYPE alpha,
       DATA_TYPE POLYBENCH_2D(imgIn, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y1, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y2, W, H, w, h)) {

    /* Create local restrict-qualified views of the 2D arrays.
       This does not change semantics (arrays are distinct) but
       gives the compiler stronger aliasing information. */
    DATA_TYPE (*restrict imgInR)[h]  = imgIn;
    DATA_TYPE (*restrict imgOutR)[h] = imgOut;
    DATA_TYPE (*restrict y1R)[h]     = y1;
    DATA_TYPE (*restrict y2R)[h]     = y2;

    DATA_TYPE k;
    DATA_TYPE a1, a2, a3, a4, a5, a6, a7, a8;
    DATA_TYPE b1, b2, c1, c2;

#pragma scop
    /* ----- Coefficient precomputation (unchanged formula) ----- */
    const DATA_TYPE one          = SCALAR_VAL(1.0);
    const DATA_TYPE two          = SCALAR_VAL(2.0);
    const DATA_TYPE alpha_local  = alpha;

    const DATA_TYPE exp_neg_alpha  = EXP_FUN(-alpha_local);
    const DATA_TYPE exp_pos_2alpha = EXP_FUN(two * alpha_local);
    const DATA_TYPE exp_neg_2alpha = EXP_FUN(-two * alpha_local);

