       equivalent to the original expression. */
    const DATA_TYPE t0 = one - exp_neg_alpha;
    const DATA_TYPE t1 = one + two * alpha_local * exp_neg_alpha - exp_pos_2alpha;
    k = (t0 * t0) / t1;

    a1 = a5 = k;
    a2 = a6 = k * exp_neg_alpha * (alpha_local - one);
    a3 = a7 = k * exp_neg_alpha * (alpha_local + one);
    a4 = a8 = -k * exp_neg_2alpha;

    b1 = POW_FUN(two, -alpha_local);
    b2 = -exp_neg_2alpha;
    c1 = c2 = one;


