        DATA_TYPE *restrict imgInRow  = imgInR[i];
        DATA_TYPE *restrict y1Row     = y1R[i];
        DATA_TYPE *restrict y2Row     = y2R[i];
        DATA_TYPE *restrict outRow    = imgOutR[i];

        /* Forward recursive filter along the row. */
        DATA_TYPE xm1 = SCALAR_VAL(0.0);
        DATA_TYPE ym1 = SCALAR_VAL(0.0);
        DATA_TYPE ym2 = SCALAR_VAL(0.0);

        for (int j = 0; j < _PB_H; ++j) {
            const DATA_TYPE x = imgInRow[j];
            const DATA_TYPE y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;
            y1Row[j] = y;

            xm1 = x;
            ym2 = ym1;
            ym1 = y;
        }

        /* Backward recursive filter along the row. */
        DATA_TYPE xp1 = SCALAR_VAL(0.0);
        DATA_TYPE xp2 = SCALAR_VAL(0.0);
        DATA_TYPE yp1 = SCALAR_VAL(0.0);
        DATA_TYPE yp2 = SCALAR_VAL(0.0);

        for (int j = _PB_H - 1; j >= 0; --j) {
            const DATA_TYPE y = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            y2Row[j] = y;

            const DATA_TYPE x = imgInRow[j];
            xp2 = xp1;
            xp1 = x;
            yp2 = yp1;
            yp1 = y;
        }

        /* Combine forward and backward results for this row. */
        for (int j = 0; j < _PB_H; ++j) {
            outRow[j] = c1 * (y1Row[j] + y2Row[j]);
        }
    }


    /* ============================================================
       Second pair of 1D recursions: vertical pass (along i)
       ------------------------------------------------------------
       Original code performed:
         4) forward pass for all columns  -> y1
         5) backward pass for all columns -> y2
         6) combine y1,y2                 -> imgOut

       Each column j is independent: recurrences are only along i.
       We therefore:
         - process each column fully (forward, backward, combine),
         - reuse the column's data while it is in cache,
         - and parallelize across columns.

       The order in which different columns are processed changes,
       but there are no cross-column dependencies, so the final
       imgOut is identical element-wise to the original version.
       ============================================================ */

#pragma omp parallel for schedule(static)
    for (int j = 0; j < _PB_H; ++j)
    {
        /* Forward recursive filter along the column. */
        DATA_TYPE tm1 = SCALAR_VAL(0.0);
        DATA_TYPE ym1 = SCALAR_VAL(0.0);
        DATA_TYPE ym2 = SCALAR_VAL(0.0);

        for (int i = 0; i < _PB_W; ++i) {
            const DATA_TYPE x = imgOutR[i][j];
            const DATA_TYPE y = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;
            y1R[i][j] = y;

            tm1 = x;
            ym2 = ym1;
            ym1 = y;
        }

        /* Backward recursive filter along the column. */
        DATA_TYPE tp1 = SCALAR_VAL(0.0);
        DATA_TYPE tp2 = SCALAR_VAL(0.0);
        DATA_TYPE yp1 = SCALAR_VAL(0.0);
        DATA_TYPE yp2 = SCALAR_VAL(0.0);

        for (int i = _PB_W - 1; i >= 0; --i) {
            const DATA_TYPE y = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
            y2R[i][j] = y;

            const DATA_TYPE x = imgOutR[i][j];
            tp2 = tp1;
            tp1 = x;
            yp2 = yp1;
            yp1 = y;
        }

        /* Final combination for this column. */
        for (int i = 0; i < _PB_W; ++i) {
            imgOutR[i][j] = c2 * (y1R[i][j] + y2R[i][j]);
        }
    }

#pragma endscop
}


int main(int argc, char** argv)
{
