                const DATA_TYPE yv = a5 * in_val + a6 * tm1 + b1 * ym1 + b2 * ym2;
                *y1_fwd = yv;                       /* y1[i][j] */

                tm1 = in_val;
                ym2 = ym1;
                ym1 = yv;

                out_fwd += h;  /* move to next row, same column */
                y1_fwd  += h;
            }

            /* Backward vertical filter: bottom to top. */
            DATA_TYPE * restrict out_bwd = &imgOut_[_PB_W - 1][j];
            DATA_TYPE * restrict y2_bwd  = &y2_[_PB_W - 1][j];

