  a2 = a6 = common * (alpha - SCALAR_VAL(1.0));
  a3 = a7 = common * (alpha + SCALAR_VAL(1.0));
  a4 = a8 = -k * exp_m_2alpha;
  b1 = pow2_m_alpha;
  b2 = -exp_m_2alpha;
  c1 = c2 = SCALAR_VAL(1.0);

  /* --------------------------------------------------------------------
   * Horizontal pass (row-wise).
   *
   * We fuse the original three row-wise loops:
   *   1. forward recursion (y1)
   *   2. backward recursion (y2)
   *   3. combination into imgOut
   *
   * into a single outer loop over rows.  Each row is completely
   * independent, so this reordering is semantically safe and improves
   * locality: all operations on a row happen while it is still hot in L1.
   * The outer loop is parallelized with OpenMP.
   * ------------------------------------------------------------------ */
#pragma omp parallel for schedule(static)
  for (int i = 0; i < w_eff; ++i)
  {
    /* Row pointers: give the compiler simple, contiguous pointers for
       better alias analysis and cache-friendly access. */
    DATA_TYPE * restrict imgIn_row  = imgIn[i];
    DATA_TYPE * restrict y1_row     = y1[i];
    DATA_TYPE * restrict y2_row     = y2[i];
    DATA_TYPE * restrict imgOut_row = imgOut[i];

    /* Forward recursive filter along the row. */
    DATA_TYPE xm1 = SCALAR_VAL(0.0);
    DATA_TYPE ym1 = SCALAR_VAL(0.0);
    DATA_TYPE ym2 = SCALAR_VAL(0.0);

    for (int j = 0; j < h_eff; ++j)
    {
      const DATA_TYPE x     = imgIn_row[j];
      const DATA_TYPE y_val = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;

      y1_row[j] = y_val;

      xm1 = x;
      ym2 = ym1;
      ym1 = y_val;
    }

    /* Backward recursive filter along the row. */
    DATA_TYPE xp1 = SCALAR_VAL(0.0);
    DATA_TYPE xp2 = SCALAR_VAL(0.0);
    DATA_TYPE yp1 = SCALAR_VAL(0.0);
    DATA_TYPE yp2 = SCALAR_VAL(0.0);

    for (int j = h_eff - 1; j >= 0; --j)
    {
      const DATA_TYPE y_val = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;

      y2_row[j] = y_val;

      xp2 = xp1;
      xp1 = imgIn_row[j];
      yp2 = yp1;
      yp1 = y_val;
    }

    /* Combine forward and backward contributions for this row. */
    for (int j = 0; j < h_eff; ++j)
    {
      imgOut_row[j] = c1 * (y1_row[j] + y2_row[j]);
    }
  }

  /* --------------------------------------------------------------------
   * Vertical pass (column-wise).
   *
   * A naive implementation would traverse columns directly, which is
   * very cache-unfriendly because successive elements are far apart in
   * memory (large stride).  Instead we:
   *
   *   1. Transpose imgOut into a temporary buffer imgOut_T.
   *   2. Perform the Deriche recursions along rows of imgOut_T (which
   *      correspond to original columns) using y1 and y2 as workspaces.
   *   3. Combine the results back into imgOut in the original layout.
   *
   * This is mathematically equivalent to the original code: each column
   * is filtered independently with identical recurrences; only the
   * in-memory layout is changed to improve locality.
   * ------------------------------------------------------------------ */

  /* Step 1: transpose imgOut (size w_eff x h_eff) into imgOut_T
     (logical size h_eff x w_eff). */
#pragma omp parallel for collapse(2) schedule(static)
  for (int i = 0; i < w_eff; ++i)
    for (int j = 0; j < h_eff; ++j)
    {
      const unsigned long long idxT =
        (unsigned long long)j * (unsigned long long)w_eff +
        (unsigned long long)i;
      imgOut_T[idxT] = imgOut[i][j];
    }

  /* Flat views of y1 and y2 used as workspaces in the transposed layout.
     From this point on we only access y1/y2 through these flat pointers,
     so it is safe to qualify them with restrict. */
  DATA_TYPE * restrict y1_buf = &y1[0][0];
  DATA_TYPE * restrict y2_buf = &y2[0][0];

  /* Step 2: for each original column j (row j in imgOut_T), apply the
     forward and backward recursions along a contiguous row of length
     w_eff. */
#pragma omp parallel for schedule(static)
  for (int j = 0; j < h_eff; ++j)
  {
    const unsigned long long base =
      (unsigned long long)j * (unsigned long long)w_eff;

    DATA_TYPE * restrict col    = imgOut_T + base;
    DATA_TYPE * restrict y1_col = y1_buf  + base;
    DATA_TYPE * restrict y2_col = y2_buf  + base;

    /* Forward recursion along this transposed row (original column). */
    DATA_TYPE tm1 = SCALAR_VAL(0.0);
    DATA_TYPE ym1 = SCALAR_VAL(0.0);
    DATA_TYPE ym2 = SCALAR_VAL(0.0);

    for (int i = 0; i < w_eff; ++i)
    {
      const DATA_TYPE x     = col[i];
      const DATA_TYPE y_val = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;

      y1_col[i] = y_val;

      tm1 = x;
      ym2 = ym1;
      ym1 = y_val;
    }

    /* Backward recursion along this transposed row (original column). */
    DATA_TYPE tp1 = SCALAR_VAL(0.0);
    DATA_TYPE tp2 = SCALAR_VAL(0.0);
    DATA_TYPE yp1 = SCALAR_VAL(0.0);
    DATA_TYPE yp2 = SCALAR_VAL(0.0);

    for (int i = w_eff - 1; i >= 0; --i)
    {
      const DATA_TYPE y_val = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;

      y2_col[i] = y_val;

      tp2 = tp1;
      tp1 = col[i];
      yp2 = yp1;
      yp1 = y_val;
    }
  }

  /* Step 3: combine y1 and y2 back into imgOut in the original layout.
     Accesses to y1_buf / y2_buf are contiguous; imgOut is written
     row-major. */
#pragma omp parallel for schedule(static)
  for (int i = 0; i < w_eff; ++i)
  {
    DATA_TYPE * restrict imgOut_row = imgOut[i];

    for (int j = 0; j < h_eff; ++j)
    {
      const unsigned long long idxT =
        (unsigned long long)j * (unsigned long long)w_eff +
        (unsigned long long)i;

      imgOut_row[j] = c2 * (y1_buf[idxT] + y2_buf[idxT]);
    }
  }

#pragma endscop

  /* Release temporary buffer. */
  free(imgOut_T);
}


